class Solution {
public:
    int minBishopMoves(vector<int>& source, vector<int>& target) {
        int dr = abs(source[0] - target[0]);
        int dc = abs(source[1] - target[1]);
        if ((dr + dc) % 2 != 0) return -1;
        if (dr == 0 && dc == 0) return 0;
        if (dr == dc) return 1;
        return 2;
    }
};
